/* Scroll-driven reveals, all CSS. Each class ties an animation to the element's own trip
   through the window (animation-timeline: view()). Browsers without scroll-driven
   animations, and anyone who prefers reduced motion, see everything in place.
   --newhalo-step (0, 1, 2 …) shifts an item's range a little later, for staggered lists.
   rise distances can be changed with --newhalo-rise (default 60px / 50px).
   --newhalo-drift sets how far "drift" travels (default 34px each way). */

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .newhalo-reveal-fade,
    .newhalo-reveal-rise,
    .newhalo-reveal-rise-sm,
    .newhalo-reveal-zoom,
    .newhalo-reveal-settle,
    .newhalo-reveal-sweep,
    .newhalo-reveal-draw,
    .newhalo-reveal-bloom {
      animation-timing-function: cubic-bezier(0.32, 0.94, 0.6, 1);
      animation-fill-mode: both;
      animation-timeline: view();
      animation-range: entry calc(5% + var(--newhalo-step, 0) * 6%) cover calc(25% + var(--newhalo-step, 0) * 6%);
    }
    .newhalo-reveal-fade { animation-name: newhalo-reveal-fade; }
    .newhalo-reveal-rise { animation-name: newhalo-reveal-rise; }
    .newhalo-reveal-rise-sm { animation-name: newhalo-reveal-rise-sm; }
    .newhalo-reveal-zoom { animation-name: newhalo-reveal-zoom; }
    .newhalo-reveal-settle { animation-name: newhalo-reveal-settle; }
    .newhalo-reveal-draw { animation-name: newhalo-reveal-draw; transform-origin: left; }

    /* sweep wipes text in from the left through a soft-edged mask */
    .newhalo-reveal-sweep {
      animation-name: newhalo-reveal-sweep;
      animation-timing-function: linear;
      mask-image: linear-gradient(90deg, var(--foreground) 40%, transparent 60%);
      mask-size: 250% 100%;
      mask-repeat: no-repeat;
    }

    /* bloom is scrubbed over a longer stretch: from the bottom edge to half-way up */
    .newhalo-reveal-bloom {
      animation-name: newhalo-reveal-bloom;
      animation-timing-function: linear;
      animation-range: entry 0% cover 50%;
    }

    /* drift is scrubbed for the whole trip: the picture slides inside its frame */
    .newhalo-reveal-drift {
      animation: newhalo-reveal-drift linear both;
      animation-timeline: view();
      animation-range: cover 0% cover 100%;
    }
  }
}

@keyframes newhalo-reveal-fade {
  from { opacity: 0; }
}
@keyframes newhalo-reveal-rise {
  from { opacity: 0; transform: translateY(var(--newhalo-rise, 60px)); }
}
@keyframes newhalo-reveal-rise-sm {
  from { opacity: 0; transform: translateY(var(--newhalo-rise, 50px)); }
}
@keyframes newhalo-reveal-zoom {
  from { opacity: 0; transform: scale(1.15); }
}
@keyframes newhalo-reveal-settle {
  from { transform: scale(1.15); }
}
@keyframes newhalo-reveal-bloom {
  from { opacity: 0; transform: scale(1.1); }
}
@keyframes newhalo-reveal-draw {
  from { transform: scaleX(0); }
}
@keyframes newhalo-reveal-sweep {
  from { mask-position: 100% 0; }
  to { mask-position: 0 0; }
}
@keyframes newhalo-reveal-drift {
  from { transform: translateY(calc(-1 * var(--newhalo-drift, 34px))); }
  to { transform: translateY(var(--newhalo-drift, 34px)); }
}

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./newhalo-reveal.css";

/**
 * fade: opacity 0→1 · rise: fade + 60px lift · rise-sm: fade + 50px lift · zoom: fade + scale
 * 1.15→1 · settle: scale 1.15→1 only (a picture inside its frame) · bloom: fade + scale
 * 1.1→1, scrubbed over a longer stretch · sweep: text wiped in from the left through a soft
 * mask · draw: a line growing from the left (scaleX 0→1) · drift: a parallax slide inside a
 * frame, scrubbed for the whole trip through the window
 */
export type NewhaloRevealEffect = "fade" | "rise" | "rise-sm" | "zoom" | "settle" | "bloom" | "sweep" | "draw" | "drift";

/** The class for an effect, to put straight on an element without a wrapper. */
export function newhaloReveal(effect: NewhaloRevealEffect) {
  return `newhalo-reveal-${effect}`;
}

/** Inline style for a staggered item (step 0, 1, 2 …) and/or a drift distance in px. */
export function newhaloRevealStyle(step = 0, drift?: number): CSSProperties {
  return { "--newhalo-step": step, ...(drift !== undefined && { "--newhalo-drift": `${drift}px` }) } as CSSProperties;
}

export interface NewhaloRevealProps {
  /** what happens as it enters the window */
  effect?: NewhaloRevealEffect;
  /** stagger position in a list: each step starts a little later */
  step?: number;
  /** for drift: how far the content slides each way, in px */
  drift?: number;
  /** the element to render */
  as?: "div" | "li" | "span" | "p";
  children?: ReactNode;
  className?: string;
}

/** Wraps content in a CSS scroll-driven reveal. Static HTML and old browsers show it in place. */
export function NewhaloReveal({ effect = "fade", step = 0, drift, as: Tag = "div", children, className }: NewhaloRevealProps) {
  return (
    <Tag className={cn(newhaloReveal(effect), className)} style={newhaloRevealStyle(step, drift)}>
      {children}
    </Tag>
  );
}
